"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError, VersionError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
SPACES = " \t"
NUMBER_RE = re.compile(r"0|[1-9][0-9]*")
WILDCARDS = ("x", "X", "*")
SPLIT_RE = re.compile(r"[ \t]+")

# Comparator kinds: ">=", ">", "<", "<=", "=". A comparator is
# (kind, Version, carries) where `carries` says the text named a prerelease.
NONE = "none"


def _bad_range(msg):
    return RangeError("bad-range", msg)


def _bad_version(msg):
    return RangeError("bad-version", msg)


def _parse_partial(text: str):
    """Returns (major, minor, patch, prerelease, build); a wildcard part is None."""
    idx = next((i for i, c in enumerate(text) if c in "-+"), len(text))
    core, rest = text[:idx], text[idx:]
    parts = core.split(".")
    if len(parts) > 3:
        raise _bad_version(f"too many parts in {text!r}")
    values = []
    wild = False
    for part in parts:
        if part in WILDCARDS:
            wild = True
            values.append(None)
        elif NUMBER_RE.fullmatch(part):
            if wild:
                raise _bad_version(f"number after a wildcard in {text!r}")
            values.append(int(part))
        else:
            raise _bad_version(f"bad part {part!r} in {text!r}")
    values += [None] * (3 - len(values))
    pre = build = ()
    if rest:
        if len(parts) != 3 or wild:
            raise _bad_version(f"prerelease or build needs three numbers in {text!r}")
        if rest[0] == "-":
            body, plus, b = rest[1:].partition("+")
            if not PRERELEASE_RE.fullmatch(body):
                raise _bad_version(f"bad prerelease in {text!r}")
            pre = tuple(body.split("."))
            if plus:
                if not BUILD_RE.fullmatch(b):
                    raise _bad_version(f"bad build in {text!r}")
                build = tuple(b.split("."))
        else:
            if not BUILD_RE.fullmatch(rest[1:]):
                raise _bad_version(f"bad build in {text!r}")
            build = tuple(rest[1:].split("."))
    return (values[0], values[1], values[2], pre, build)


def _full(p):
    return Version(p[0], p[1], p[2], p[3], p[4])


def _is_full(p):
    return p[2] is not None


def _low(major, minor=0, patch=0):
    return Version(major, minor, patch)


def _before(major, minor=0, patch=0):
    """`<major.minor.patch-0`: lower than every version of that release."""
    return ("<", Version(major, minor, patch, ("0",)), False)


def _block_end(p):
    """Comparator `<` the whole block of a partial with a major part."""
    if p[1] is None:
        return _before(p[0] + 1)
    return _before(p[0], p[1] + 1)


def _comparators(op, p):
    """Desugar one comparator; returns a list of comparators, [] for any, NONE for no version."""
    if p[0] is None:
        return NONE if op in ("<", ">") else []
    if _is_full(p):
        v = _full(p)
        carries = bool(p[3])
        if op in ("", "="):
            return [("=", v, carries)]
        if op == "^":
            return [(">=", v, carries), _before(p[0] + 1)]
        if op == "~":
            return [(">=", v, carries), _before(p[0], p[1] + 1)]
        return [(op, v, carries)]
    lower = _low(p[0], p[1] or 0, 0)
    if op == "^":
        return [(">=", lower, False), _before(p[0] + 1)]
    if op == "~":
        return [(">=", lower, False), _block_end(p)]
    if op in ("", "="):
        return [(">=", lower, False), _block_end(p)]
    if op == ">=":
        return [(">=", lower, False)]
    if op == ">":
        end = _block_end(p)[1]
        return [(">=", Version(end.major, end.minor, end.patch), False)]
    if op == "<":
        return [_before(p[0], p[1] or 0)]
    return [_block_end(p)]  # "<="


def _hyphen(a, b):
    out = []
    if a[0] is not None:
        out.append((">=", _full(a) if _is_full(a) else _low(a[0], a[1] or 0, 0), bool(a[3])))
    if b[0] is not None:
        if _is_full(b):
            out.append(("<=", _full(b), bool(b[3])))
        else:
            out.append(_block_end(b))
    return out


def _check(kind, cv, v):
    if kind == "=":
        return v == cv
    if kind == ">=":
        return v >= cv
    if kind == ">":
        return v > cv
    if kind == "<":
        return v < cv
    return v <= cv


class Range:
    def __init__(self, text: str, alternatives, exact: bool):
        self.text = text
        self._alts = alternatives  # list of comparator lists, or NONE
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        for alt in self._alts:
            if alt == NONE:
                continue
            if not all(_check(k, cv, version) for k, cv, _ in alt):
                continue
            if version.is_prerelease() and not any(
                carries and cv.release == version.release for _, cv, carries in alt
            ):
                continue
            return True
        return False

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/resolve.md, section 4)."""
        return self._exact

    def __str__(self):
        return self.text


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise _bad_range(f"a range is a string, not {type(text).__name__}")
    if not text.strip(SPACES):
        raise _bad_range("empty range")
    alts = text.split("||")
    if any(not a.strip(SPACES) for a in alts):
        raise _bad_range("empty alternative")
    # Shape of every alternative first (steps 3 to 5), then the versions (step 6).
    shaped = []
    for a in alts:
        tokens = SPLIT_RE.split(a.strip(SPACES))
        if "-" in tokens:
            if len(tokens) != 3 or tokens[1] != "-":
                raise _bad_range(f"misplaced '-' in {a!r}")
            if tokens[0].startswith(OPERATORS) or tokens[2].startswith(OPERATORS):
                raise _bad_range(f"operator in a hyphen range {a!r}")
            shaped.append(("hyphen", tokens[0], tokens[2]))
            continue
        items = []
        for tok in tokens:
            op = next((o for o in OPERATORS if tok.startswith(o)), "")
            rest = tok[len(op):]
            if not rest or not (rest[0].isascii() and rest[0].isdigit() or rest[0] in WILDCARDS):
                raise _bad_range(f"cannot read {tok!r}")
            items.append((op, rest))
        shaped.append(("set", items))
    result = []
    exact = False
    for s in shaped:
        if s[0] == "hyphen":
            result.append(_hyphen(_parse_partial(s[1]), _parse_partial(s[2])))
            continue
        parsed = [(op, _parse_partial(rest)) for op, rest in s[1]]
        comps = []
        dead = False
        for op, p in parsed:
            c = _comparators(op, p)
            if c == NONE:
                dead = True
            else:
                comps.extend(c)
        result.append(NONE if dead else comps)
        if len(alts) == 1 and len(parsed) == 1:
            op, p = parsed[0]
            exact = op in ("", "=") and _is_full(p)
    return Range(text, result, exact)
